["^(\\d+(?: \\d{3})*(?:[.,]\\d+)?) (?:тетрадь|тетради|тетрадей): (\\d+(?: \\d{3})*(?:[.,]\\d+)?) · (\\d+(?: \\d{3})*(?:[.,]\\d+)?) = (\\d+(?: \\d{3})*(?:[.,]\\d+)?) тг$", "${1} дәптер: ${2} · ${3} = ${4} тг"],
["^Вместе за час: (\\d+(?: \\d{3})*(?:[.,]\\d+)?) \\+ (\\d+(?: \\d{3})*(?:[.,]\\d+)?) = (\\d+(?: \\d{3})*(?:[.,]\\d+)?) м³\\.$", "Бірге бір сағатта: ${1} + ${2} = ${3} м³."],
["^Всего частей: (\\d+(?: \\d{3})*(?:[.,]\\d+)?) \\+ (\\d+(?: \\d{3})*(?:[.,]\\d+)?) = (\\d+(?: \\d{3})*(?:[.,]\\d+)?)\\. Одна часть: (\\d+(?: \\d{3})*(?:[.,]\\d+)?) : (\\d+(?: \\d{3})*(?:[.,]\\d+)?) = (\\d+(?: \\d{3})*(?:[.,]\\d+)?)\\.$", "Барлық бөлік: ${1} + ${2} = ${3}. Бір бөлік: ${4} : ${5} = ${6}."],
["^Доля «([^»]+)»: (\\d+(?: \\d{3})*(?:[.,]\\d+)?) · (\\d+(?: \\d{3})*(?:[.,]\\d+)?) = (\\d+(?: \\d{3})*(?:[.,]\\d+)?)$", "«${1}» үлесі: ${2} · ${3} = ${4}", ["1:tr"]],
["^Рабочих стало больше в (\\d+(?: \\d{3})*(?:[.,]\\d+)?) (?:раз|раза) — времени потребуется в (\\d+(?: \\d{3})*(?:[.,]\\d+)?) (?:раз|раза) меньше\\.$", "Жұмысшылар ${1} есе көп болды — уақыт ${2} есе аз қажет болады."],
["^Всего частей: (\\d+(?: \\d{3})*(?:[.,]\\d+)?) \\+ (\\d+(?: \\d{3})*(?:[.,]\\d+)?) \\+ (\\d+(?: \\d{3})*(?:[.,]\\d+)?) = (\\d+(?: \\d{3})*(?:[.,]\\d+)?)\\. Одна часть: (\\d+(?: \\d{3})*(?:[.,]\\d+)?) : (\\d+(?: \\d{3})*(?:[.,]\\d+)?) = (\\d+(?: \\d{3})*(?:[.,]\\d+)?)\\.$", "Барлық бөлік: ${1} + ${2} + ${3} = ${4}. Бір бөлік: ${5} : ${6} = ${7}."],
["^У третьего: (\\d+(?: \\d{3})*(?:[.,]\\d+)?) · (\\d+(?: \\d{3})*(?:[.,]\\d+)?) = (\\d+(?: \\d{3})*(?:[.,]\\d+)?)$", "Үшіншісінде: ${1} · ${2} = ${3}"]
